 const p=pinocchios.find(p=>p.id===r.pinocchio_id),project=projects.find(p=>p.id===r.project_id),active=!['succeeded','failed','stopped','skipped'].includes(r.state);
 const views=[['charts','Charts'],['overview','Overview'],['logs','Logs'],['files','Files'],['execution','Execution'],...(r.category==='ball-detection'?[['errors','Error analysis']]:[])];
 const view=views.some(([key])=>key===route().get('view'))?route().get('view'):'charts';
